import { db } from './db.js';

export function getUser(req, res) {
  const user = db.users.byId(req.params.id);
  if (!user) {
    res.status(404).end();
    return;
  }
  res.send(user);
}

export function searchUsers(req, res) {
  const q = req.query.q;
  if (!q) {
    res.status(400).end();
    return;
  }
  const rows = db.users.search(q);
  const html = '<ul>' + rows.map((r) => '<li>' + r.name + '</li>').join('') + '</ul>';
  res.send(html);
}

